/* ---------- 3 · Operadores y f-strings ---------- */
const aritmetica=crearGen({titulo:'Operadores y precedencia',
  explicacion:'Operadores: <code>+ - *</code>, <code>/</code> (división, <b>siempre da float</b>: 8 / 2 → 4.0), <code>//</code> (división entera: 7 // 2 → 3), <code>%</code> (residuo: 7 % 2 → 1) y <code>**</code> (potencia: 2 ** 3 → 8). Precedencia: primero <code>**</code>, luego <code>* / // %</code>, al final <code>+ -</code>; los paréntesis van antes que todo.',
  alternativa:'// es «¿cuántas cajas completas llenas?» y % es «¿cuántos sobran?». Con 7 huevos en cajas de 2: 3 cajas y sobra 1.',
  referencia:'PCEP 1.3 – Operadores y prioridad · OpenStax Python cap. 2',regla:'/ da float; // división entera; % residuo; ** potencia; ** > * / // % > + −; los paréntesis primero.',
  pista:'Primero ** , luego * / // %, al final + −.',
  tarjetas:[['8 / 2','4.0 (la / siempre da float).'],['17 // 5 y 17 % 5','3 y 2.'],['2 + 3 * 4','14 (primero la multiplicación).'],['2 ** 3','8']],
  plantillas:{
    b1:{prof:'basico',f:(n,rng)=>{const b=rng.entero(2,6),q=rng.entero(2,8+n),r=rng.entero(1,b-1),a=b*q+r;return predice({codigo:`print(${a} // ${b})\nprint(${a} % ${b})`,salida:`${q}\n${r}`,
      traza:[['// cuántas veces cabe completo',`${a} // ${b} = ${q}`,`${b} × ${q} = ${b*q}.`],['% lo que sobra',`${a} − ${b*q} = ${r}`,'El residuo.']],
      errores:[[`${pyNum(a/b)} ${r}`,'// quita los decimales.'],[`${r} ${q}`,'// da el cociente y % el residuo.'],[`${q} 0`,'Sí sobra algo.']]})}},
    b2:{prof:'basico',f:(n,rng)=>{const b=rng.entero(2,9),q=rng.entero(2,10);return predice({codigo:`print(${b*q} / ${b})`,salida:pyNum(q,true),
      traza:[['/ siempre da float',`${b*q} / ${b} = ${q}.0`,'Aunque sea exacta.']],
      errores:[[q,'La / siempre da un float: lleva .0.'],[`${q}.00`,'Python muestra un solo 0.']]})}},
    p1:{prof:'procedimiento',f:(n,rng)=>{const a=R(n,rng),b=rng.entero(2,6),c=rng.entero(2,6);return predice({codigo:`print(${a} + ${b} * ${c})`,salida:a+b*c,
      traza:[['Primero la multiplicación',`${b} * ${c} = ${b*c}`,'* va antes que +.'],['Luego la suma',`${a} + ${b*c} = ${a+b*c}`,'Al final.']],
      errores:[[(a+b)*c,'Primero se multiplica, luego se suma.'],[`${a+b*c}.0`,'Con enteros y sin / el resultado es entero.']]})}},
    p2:{prof:'procedimiento',f:(n,rng)=>{const a=rng.entero(2,4),b=rng.entero(2,3),c=rng.entero(2,9);return predice({codigo:`print(${c} * ${a} ** ${b})\nprint((${c} * ${a}) ** ${b})`,salida:`${c*a**b}\n${(c*a)**b}`,
      traza:[['** va antes que *',`${a} ** ${b} = ${a**b}, luego ${c} × ${a**b} = ${c*a**b}`,'La potencia primero.'],['Con paréntesis cambia',`(${c*a}) ** ${b} = ${(c*a)**b}`,'Los paréntesis van antes que todo.']],
      errores:[[`${(c*a)**b} ${(c*a)**b}`,'Sin paréntesis, ** va primero.'],[`${c*a*b} ${(c*a)*b}`,'** es potencia, no multiplicación.']]})}},
    a1:{prof:'aplicacion',f:(n,rng)=>{const p=rng.entero(5,12),t=p*rng.entero(3,9)+rng.entero(1,p-1);return completa({codigo:`personas = ${t}\nlugares_por_auto = ${p}\nautos_llenos = personas ___ lugares_por_auto\nprint(autos_llenos)`,respuestas:['//'],salida:Math.floor(t/p),
      enun:`${t} personas viajan en autos de ${p} lugares. Completa el operador para saber cuántos autos van <b>completamente llenos</b>.`,
      traza:[['Autos completos = división entera',`${t} // ${p} = ${Math.floor(t/p)}`,'Sin decimales.']],
      errores:[['/','/ daría decimales.'],['%','% da las personas que sobran.'],['*','Es una división.']]})}},
    a2:{prof:'aplicacion',f:(n,rng)=>{const x=rng.entero(10,99);return completa({codigo:`n = ${x}\nif n ___ 2 == 0:\n    print("par")\nelse:\n    print("impar")`,respuestas:['%'],salida:x%2?'impar':'par',
      enun:'Completa el operador para saber si un número es par.',
      traza:[['Par = residuo 0 al dividir entre 2',`${x} % 2 = ${x%2}`,'El residuo dice si sobra algo.']],
      errores:[['//','// da el cociente, no el residuo.'],['/','/ da decimales.'],['**','Es el residuo.']]})}}
  },niveles:NIV});

